parameters.jsCode:
const rawText = $input.item.json.text || '';
const cleaned = rawText.replace(/```json|```/g, '').trim();
const parsed = JSON.parse(cleaned);
const originalTicket = $('Fetch Pending Tickets (Google Sheets)').item.json;

return {
  json: {
    ticket_id: originalTicket.ticket_id,
    stakeholder_type: parsed.stakeholder_type,
    intent_category: parsed.intent_category,
    sentiment: parsed.sentiment,
    urgency_sla: parsed.urgency_sla,
    recommended_action: parsed.recommended_action,
    suggested_reply: parsed.suggested_reply,
    status: 'TRIAGED_BY_AI'
  }
};
